function stationOptions(system){return '<optgroup label="Space stations">'+demo.campaign.stations.items.filter(s=>BODIES[s.host].system===system).map(s=>'<option value="station:'+s.id+'">◇ '+escapeOption(s.name)+'</option>').join('')+'</optgroup>';}
function flagOptions(id){return demo.campaign.progress.flags.filter(f=>BODIES[f.body].system===id).map(f=>'<option value="flag:'+f.id+'">⚑ '+escapeOption(f.name)+'</option>').join('');}
function refreshDestinations(){const current=systemAt(demo.ship),signature=current+'|'+mapSystem+'|'+LANDABLE_IDS.filter(id=>demo.campaign.hasBase(id)).join(',')+'|'+demo.campaign.stations.revision+'|'+demo.campaign.progress.flags.map(f=>f.id+f.name).join('|');if(signature===destinationSignature)return;destinationSignature=signature;const worlds=LANDABLE_IDS.filter(id=>BODIES[id].system===current);if(!worlds.includes(demo.target)){demo.target=worlds[0];demo.targetNormal=null;targetBase=false;selectedFlag=null;}const value=selectedStation?'station:'+selectedStation:selectedPortal?'gate:'+selectedPortal:selectedFlag?'flag:'+selectedFlag:targetBase?'base:'+demo.target:demo.target;$('#destination').innerHTML='<optgroup label="Worlds">'+worlds.map(id=>'<option value="'+id+'">'+BODIES[id].name+' · '+bodyClass(id)+'</option>').join('')+'</optgroup><optgroup label="Base flags">'+worlds.filter(id=>demo.campaign.hasBase(id)).map(id=>'<option value="base:'+id+'">⚑ '+BODIES[id].name+' Base #1</option>').join('')+flagOptions(current)+'</optgroup>'+stationOptions(current)+'<optgroup label="Wormholes">'+WORMHOLES.filter(g=>g.system===current).map(g=>'<option value="gate:'+g.id+'">◉ '+g.name+'</option>').join('')+'</optgroup>';$('#destination').value=value;const old=$('#map-object').value;$('#map-object').innerHTML='<optgroup label="Worlds">'+systemBodies(mapSystem).map(id=>'<option value="'+id+'">'+BODIES[id].name+' · '+bodyClass(id)+'</option>').join('')+'</optgroup><optgroup label="Base flags">'+LANDABLE_IDS.filter(id=>BODIES[id].system===mapSystem&&demo.campaign.hasBase(id)).map(id=>'<option value="base:'+id+'">⚑ '+BODIES[id].name+' Base #1</option>').join('')+flagOptions(mapSystem)+'</optgroup>'+stationOptions(mapSystem)+'<optgroup label="Wormholes">'+WORMHOLES.filter(g=>g.system===mapSystem).map(g=>'<option value="gate:'+g.id+'">◉ '+g.name+'</option>').join('')+'</optgroup>';if([...$('#map-object').options].some(o=>o.value===old))$('#map-object').value=old;else $('#map-object').value=SYSTEMS[mapSystem].star;$('#map-system').value=mapSystem;$('#map-jump').disabled=current===mapSystem;}
function fitSystem(){const s=SYSTEMS[mapSystem];mapFocus=V(BODIES[s.star].position);mapDistance=s.extent*2.8;mapWide=true;$('#map-object').value=s.star;$('#map-scale').textContent='Local view';$('#map-fly').disabled=true;$('#map-fly').textContent='No solid surface';$('#map-info').textContent=s.name+' · '+s.class+' · '+systemSurvey(mapSystem).bodies+' worlds · drag to pan · scroll to zoom';}
function viewStarSystem(id,arrived=false){if(!SYSTEMS[id])return;mapSystem=id;destinationSignature='';refreshDestinations();fitSystem();showMenu(false);showSystem(!arrived);cameraReady=false;previousFlight=false;if(arrived){document.body.classList.add('wormhole-transit');setTimeout(()=>document.body.classList.remove('wormhole-transit'),900);selectedPortal=null;selectedFlag=null;targetBase=false;syncAim();toast('Stellar jump complete. Choose a destination to land.');sound.event('stellar-jump');save();}}
function navigateFlag(f){if(!f)return;selectedPortal=null;if(BODIES[f.body].system!==systemAt(demo.ship)){toast('Jump to '+SYSTEMS[BODIES[f.body].system].name+' before flying to this flag.');return;}demo.target=f.body;demo.targetNormal=[...f.normal];targetBase=true;selectedFlag=f.id;frontier.open(false);$('#travel').click();}
$('#map-system').onchange=()=>viewStarSystem($('#map-system').value);$('#map-jump').onclick=()=>{const r=demo.jumpSystem(mapSystem);toast(r.reason);if(r.ok)viewStarSystem(mapSystem,true);};
$('#map-in').onclick=()=>mapDistance=clamp(mapDistance*.7,20,20000000);$('#map-out').onclick=()=>mapDistance=clamp(mapDistance/.7,20,20000000);$('#map-fit').onclick=fitSystem;$('#map-ship').onclick=()=>{mapSystem=systemAt(demo.position);destinationSignature='';refreshDestinations();mapFocus=V(demo.position);mapDistance=Math.max(400,nearestBody(demo.position).body.radius*5);};$('#map-left').onclick=()=>mapYaw-=Math.PI/8;$('#map-right').onclick=()=>mapYaw+=Math.PI/8;
$('#map-object').onchange=()=>{const value=$('#map-object').value;if(value.startsWith('station:')){const station=demo.campaign.stations.get(value.slice(8));if(!station)return;mapFocus=V(stationPose(station,demo.campaign.elapsed).position);mapDistance=450;$('#map-info').textContent=station.name+' · '+BODIES[station.host].name+' orbit · '+station.modules.length+' modules';$('#map-fly').disabled=!station.modules.some(n=>n.type==='dock'||n.type==='shipyard');$('#map-fly').textContent='Rendezvous & dock';return;}if(value.startsWith('gate:')){const gate=wormhole(value.slice(5));mapFocus=V(wormholePoint(gate,demo.campaign.elapsed));mapDistance=16000;$('#map-info').textContent=gate.name+' · orbiting '+BODIES[gate.host].name+' → '+SYSTEMS[wormhole(gate.peer).system].name;$('#map-fly').disabled=false;$('#map-fly').textContent='Fly to wormhole';return;}const f=value.startsWith('flag:')?demo.campaign.progress.flags.find(f=>f.id===value.slice(5)):null,isBase=!!f||value.startsWith('base:'),b=BODIES[f?.body||value.replace('base:','')];if(!b)return;mapFocus=isBase?V(f?groundPoint(f.body,f.normal):landingPoint(b.id)):V(b.position);mapDistance=isBase?400:b.radius*7;$('#map-info').textContent=f?f.name+' · '+b.name:isBase?b.name+' Base #1 · autopilot destination':bodySummary(b.id);$('#map-fly').disabled=!b.landable;$('#map-fly').textContent=isBase?'Land at flag':b.landable?'Fly to '+b.name:'No solid surface';};
$('#map-fly').onclick=()=>{const value=$('#map-object').value;if(mapSystem!==systemAt(demo.ship)){toast('Use Jump here to reach this system first.');return;}selectDestination(value);if(!selectedPortal&&!selectedStation&&!BODIES[demo.target].landable)return;$('#travel').click();};
$('#rover').onclick=()=>{unlock();if(demo.mode==='rover'){demo.exitRover();toast('Back on foot.');}else if(demo.enterRover()){yaw=demo.rovers[demo.body].heading;pitch=.3;distance=15;toast('W/S drive · A/D steer · Space handbrake · R exit.');}else toast('Walk within 6 m of your rover.');};for(const flag of document.querySelectorAll('[data-base]'))flag.onclick=()=>{selectedPortal=null;selectedFlag=null;demo.target=flag.dataset.base;demo.targetNormal=[0,1,0];targetBase=true;$('#travel').click();};
refreshDestinations();fitSystem();if(demo.landing){started=true;showMenu(false);showSystem(false);}updateHUD();requestAnimationFrame(frame);
